import { randomUUID } from "node:crypto";

/**
 * Correlation ID header name (STACK.md decision #8). Generated by the shell (or any API
 * client) if absent on outgoing requests; propagated unchanged by `auth-service` and
 * `conversation-service` into their structured logs and echoed back on the response.
 */
export const CORRELATION_HEADER = "X-Correlation-Id";

/** Minimal shape both browser `Headers` and Node's plain header objects satisfy. */
export interface HeaderReader {
  get(name: string): string | null | undefined;
}

/**
 * Reads the correlation ID off an incoming request's headers, generating a fresh UUID if
 * one isn't already present. Works with both a `Headers`-like object (browser `fetch`,
 * Express via a thin adapter) and a plain lowercase-keyed record (Node `IncomingMessage`,
 * pino context).
 */
export function getOrCreateCorrelationId(
  headers: HeaderReader | Record<string, string | string[] | undefined>,
): string {
  const existing = isHeaderReader(headers)
    ? headers.get(CORRELATION_HEADER)
    : headers[CORRELATION_HEADER] ?? headers[CORRELATION_HEADER.toLowerCase()];

  const value = Array.isArray(existing) ? existing[0] : existing;

  return value && value.length > 0 ? value : randomUUID();
}

function isHeaderReader(value: unknown): value is HeaderReader {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as HeaderReader).get === "function"
  );
}
